440	     * The maximum number of owners that may be registered on a single day. Once this many owners
441	     * already share a {@code registrationDate}, creating another owner for that day is rejected.
442	     */
443	    private static final int MAX_OWNERS_PER_DAY = 100;
444	
445	    /**
446	     * Rejects creating an owner on a day that has already reached {@link #MAX_OWNERS_PER_DAY} or more
447	     * owner registrations. Existing owners are counted by their {@code registrationDate} matching the
448	     * registration date of the owner being created.
449	     *
450	     * @param registrationDate the registration date of the owner being created
451	     * @throws DailyOwnerLimitExceededException if the day has already reached the maximum number of owners
452	     */
453	    /**
454	     * Rolls an effective registration date forward onto a business day. A registration date must fall
455	     * on a weekday: when the supplied or defaulted date is a Saturday or Sunday it is rolled forward to
456	     * the next Monday and that adjusted date becomes the owner's {@code registrationDate}. A weekday date
457	     * is returned unchanged. Every value derived from the registration date (the daily create-limit
458	     * count, the membership number's year segment, and so on) uses this adjusted date.
459	     *
460	     * @param date the effective registration date (supplied in the request or defaulted to the server date)
461	     * @return the same date if it is a weekday, otherwise the following Monday
462	     */
463	    private LocalDate rollToBusinessDay(LocalDate date) {
464	        DayOfWeek day = date.getDayOfWeek();
465	        if (day == DayOfWeek.SATURDAY) {
466	            return date.plusDays(2);
467	        }
468	        if (day == DayOfWeek.SUNDAY) {
469	            return date.plusDays(1);
470	        }
471	        return date;
472	    }
473	
474	    private void rejectDailyLimitReached(LocalDate registrationDate) {
475	        long ownersToday = this.clinicService.findAllOwners().stream()
476	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
477	            .count();
478	        if (ownersToday >= MAX_OWNERS_PER_DAY) {
479	            throw new DailyOwnerLimitExceededException(registrationDate);
480	        }
481	    }
482	
483	    /**
484	     * The number of owners that must already share a {@code registrationDate} before a newly created
485	     * owner for that day is flagged with a bulk-signup warning. Once more than this many owners have
486	     * been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
487	     */
488	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
489	
490	    /**
491	     * Determines whether the owner being created should carry a bulk-signup warning. The warning is
492	     * raised when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for
493	     * the same registration date at the time this owner is created. Existing owners are counted by their
494	     * {@code registrationDate} matching the registration date of the owner being created, mirroring the
495	     * daily create-limit accumulation.
496	     *
497	     * @param registrationDate the registration date of the owner being created
498	     * @return {@code true} if the day already holds more than the threshold number of owners
499	     */
500	    private boolean isBulkSignupDay(LocalDate registrationDate) {
501	        long ownersToday = this.clinicService.findAllOwners().stream()
502	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
503	            .count();
504	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
505	    }
506	
507	    private void rejectCityAtCapacity(String city) {
508	        String normalizedCity = normalizeForComparison(city);
509	        long ownersInCity = this.clinicService.findAllOwners().stream()
510	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
511	            .count();
512	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
513	            throw new OwnerCityCapacityExceededException(city);
514	        }
515	    }
516	
517	    /**
518	     * Rejects creating an owner whose last name and address both match an existing owner. Both fields
519	     * are compared case-insensitively with surrounding and repeated internal whitespace collapsed, so
520	     * that e.g. {@code "  110  W. Liberty  St. "} and {@code "110 w. liberty st."} are treated as the
521	     * same address. This guard is bypassed for a request that sets {@code sharesHousehold} true.
522	     *
