274	    /**
275	     * Counts how many existing owners share the given first and last name, compared
276	     * case-insensitively, at the moment before the new owner is persisted. The result is
277	     * stored on the owner as its {@code namesakeCount}, so it reflects the population as it
278	     * stood when the owner was created rather than being recomputed on later reads.
279	     *
280	     * @param firstName the first name of the owner being created
281	     * @param lastName the last name of the owner being created
282	     * @return the number of pre-existing owners with the same first and last name
283	     */
284	    private int countNamesakes(String firstName, String lastName) {
285	        String first = firstName == null ? "" : firstName;
286	        String last = lastName == null ? "" : lastName;
287	        return (int) this.clinicService.findAllOwners().stream()
288	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
289	                && last.equalsIgnoreCase(existing.getLastName()))
290	            .count();
291	    }
