294	        String cityLetters = city == null ? "" : city;
295	        String city3 = cityLetters.substring(0, Math.min(3, cityLetters.length())).toUpperCase(Locale.ROOT);
296	        String letters = lastName == null ? "" : lastName;
297	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
298	        String normalizedCity = normalizeForComparison(city);
299	        int sequence = (int) this.clinicService.findAllOwners().stream()
300	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
301	            .count() + 1;
302	        return String.format("%s-%s-%04d", city3, last3, sequence);
303	    }

